-- service_role (audit 2026-08-22, SEC-13) -----------------------------------
--
-- Every `service_role` statement from the baseline, in one guarded block —
-- "what does the service identity hold" is one place to read. The role is
-- created by Neon's Data API provisioning, so on a bare database it does not
-- exist yet and an unguarded GRANT here aborted the whole file — the same
-- reason db/neon-bootstrap.sql:105-118 guards its own grants. Grants for
-- post-squash objects live in the hand-maintained tail below.
do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'service_role') then
    raise notice 'role service_role not present (Data API not provisioned) — skipping';
    return;
  end if;

  grant usage on schema public to service_role;

  grant all on function public.claim_ai_call(p_user uuid, p_kind text, p_free_monthly integer, p_plus_monthly integer, p_daily_cap integer) to service_role;
  grant all on function public.clear_stale_out_items(p_household_id uuid) to service_role;
  grant all on function public.create_catalog_item(p_user uuid, p_name text, p_category public.food_category, p_shelf_life jsonb, p_barcodes text[], p_nutrition jsonb, p_source text, p_daily_cap integer) to service_role;
  grant all on function public.create_household(p_name text) to service_role;
  grant all on function public.handle_new_user() to service_role;
  grant all on function public.is_household_member(h uuid) to service_role;
  grant all on function public.join_household(p_code text) to service_role;
  grant all on function public.merge_add_items(p_household_id uuid, p_items jsonb) to service_role;
  grant all on function public.normalize_item_name(p_name text) to service_role;
  grant all on function public.refund_ai_call(p_user uuid, p_claim uuid) to service_role;
  grant all on function public.set_updated_at() to service_role;
  grant all on function public.shares_household_with(other uuid) to service_role;

  grant all on table public.ai_calls to service_role;
  grant all on table public.catalog_items to service_role;
  grant all on table public.entitlements to service_role;
  grant all on table public.grocery_items to service_role;
  grant all on table public.household_members to service_role;
  grant all on table public.households to service_role;
  grant all on table public.inventory_items to service_role;
  grant all on table public.profiles to service_role;
  grant all on table public.recipe_ingredients to service_role;
  grant all on table public.recipe_reports to service_role;
  grant all on table public.recipe_saves to service_role;
  grant all on table public.recipes to service_role;
  grant all on table public.storage_locations to service_role;
  grant all on table public.zones to service_role;
end $$;

