-- 0046: the audit's hardening pass. Everything below NARROWS what the block at
-- the top of this file grants, which is why the order matters.

-- SEC-02. TRUNCATE is not RLS-governed, and post-0036 no table has an anon
-- policy — so the unauthenticated role's grants admit nothing and should not
-- exist. Same role-exists loop as the migration, for the same portability
-- reason (`anon` on Supabase, `anonymous` on Neon).
do $$
declare
  v_role text;
  v_fn   text;
begin
  foreach v_role in array array['anon', 'anonymous', 'authenticated'] loop
    if exists (select 1 from pg_roles where rolname = v_role) then
      execute format('revoke truncate on all tables in schema public from %I', v_role);
    end if;
  end loop;

  foreach v_role in array array['anon', 'anonymous'] loop
    if not exists (select 1 from pg_roles where rolname = v_role) then
      continue;
    end if;
    execute format('revoke all on all tables in schema public from %I', v_role);
    execute format('revoke all on all sequences in schema public from %I', v_role);
    for v_fn in
      select p.oid::regprocedure::text
        from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace,
             aclexplode(p.proacl) a
       where n.nspname = 'public'
         and p.proacl is not null
         and a.grantee = (select r.oid from pg_roles r where r.rolname = v_role)
    loop
      execute format('revoke all on function %s from %I', v_fn, v_role);
    end loop;
  end loop;
end $$;

